This is a multithreaded, cache-friendly segmented sieve of Eratosthenes in C. It sieves only odd numbers, splits the range into cache-sized segments, and counts primes in parallel with OpenMP.

```c
// Build: gcc -O3 -march=native -fopenmp primes.c -o primes -lm
// Run:   ./primes      (expected output: 50847534)

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <omp.h>

#define N   1000000000ULL      /* count primes < N */
#define SEG (1u << 18)         /* odd numbers per segment (256 KiB) */

int main(void) {
    const uint64_t limit = N - 1;

    /* r = floor(sqrt(limit)) */
    uint64_t r = (uint64_t)sqrt((double)limit);
    while (r * r > limit) r--;
    while ((r + 1) * (r + 1) <= limit) r++;

    /* Base primes up to r */
    uint8_t  *composite = calloc(r + 1, 1);
    uint32_t *base      = malloc(sizeof(uint32_t) * (r + 1));
    size_t nb = 0;
    for (uint64_t i = 2; i <= r; i++) {
        if (!composite[i]) {
            base[nb++] = (uint32_t)i;
            for (uint64_t j = i * i; j <= r; j += i) composite[j] = 1;
        }
    }
    free(composite);

    /* Prime 2 is counted separately; sieve odd numbers in [3, limit] */
    uint64_t count = 1;
    const uint64_t first     = 3;
    const uint64_t total_odd = (limit - first) / 2 + 1;
    const uint64_t nseg      = (total_odd + SEG - 1) / SEG;

    #pragma omp parallel for schedule(dynamic) reduction(+:count)
    for (int64_t s = 0; s < (int64_t)nseg; s++) {
        uint64_t lo  = first + 2 * (uint64_t)s * SEG;   /* first odd value */
        uint64_t cnt = SEG;
        if ((uint64_t)s == nseg - 1)
            cnt = total_odd - (uint64_t)s * SEG;
        uint64_t hi  = lo + 2 * (cnt - 1);              /* last odd value */

        uint8_t *buf = malloc(cnt);
        memset(buf, 1, cnt);                            /* 1 = still prime */

        /* Cross off odd multiples of each odd base prime */
        for (size_t k = 1; k < nb; k++) {
            uint64_t p = base[k];
            if (p * p > hi) break;

            uint64_t m = (lo + p - 1) / p * p;          /* first multiple >= lo */
            if (m < p * p) m = p * p;                   /* never cross off p itself */
            if ((m & 1) == 0) m += p;                   /* make it odd */

            for (uint64_t j = (m - lo) / 2; j < cnt; j += p)
                buf[j] = 0;                             /* step 2p in value = p in index */
        }

        uint64_t c = 0;
        for (uint64_t j = 0; j < cnt; j++) c += buf[j];
        count += c;
        free(buf);
    }

    printf("%llu\n", (unsigned long long)count);

    free(base);
    return 0;
}
```

The answer is π(10⁹) = 50,847,534. I haven't compiled or run this in the sandbox, so please check the output and time it (`time ./primes`) on your machine. On a modern multicore CPU it should finish in well under a second.

Further gains would come from a bit-packed sieve (1 bit per odd number), a mod-30 wheel, or a hand-tuned assembly inner loop, but the gains beyond this design are usually modest.

This uses a **segmented sieve of Eratosthenes** over odd numbers only, with cache-sized blocks and OpenMP across blocks. It should count primes below 10⁹ in well under a second on a modern multicore machine.

```c
// primes_1e9.c
// Counts primes < 1,000,000,000. Expected result: 50,847,534
//
// Build: gcc -O3 -march=native -fopenmp primes_1e9.c -o primes_1e9
// Run:   ./primes_1e9

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define N        1000000000ULL      // count primes < N
#define SQRT_N   31623              // ceil(sqrt(N))
#define SEG      (1u << 16)         // odd numbers per segment (64 KiB, cache-friendly)

int main(void)
{
    // 1. Base primes up to sqrt(N), odd only (2 is counted separately).
    static uint8_t comp[SQRT_N + 1];
    static uint32_t base[4096];
    size_t nbase = 0;
    for (uint32_t i = 3; i <= SQRT_N; i += 2) {
        if (!comp[i]) {
            base[nbase++] = i;
            for (uint64_t m = (uint64_t)i * i; m <= SQRT_N; m += 2 * i)
                comp[m] = 1;
        }
    }

    // 2. Index j represents the odd number v = 2j + 1, for j in [0, J).
    //    J = N/2 covers every odd value below N.
    const uint64_t J = N / 2;
    const uint64_t nseg = (J + SEG - 1) / SEG;

    uint64_t total = 1;                // the prime 2

    #pragma omp parallel reduction(+:total)
    {
        uint8_t *buf = malloc(SEG);    // 1 = composite, 0 = (so far) prime

        #pragma omp for schedule(dynamic, 4)
        for (int64_t k = 0; k < (int64_t)nseg; k++) {
            const uint64_t j0  = (uint64_t)k * SEG;
            const uint64_t cnt = (J - j0 < SEG) ? (J - j0) : SEG;
            const uint64_t j1  = j0 + cnt;

            memset(buf, 0, cnt);
            if (k == 0) buf[0] = 1;    // the number 1 is not prime

            // 3. Cross off odd multiples of each odd base prime p,
            //    starting at p*p. Step is p in j-space (2p in value-space).
            for (size_t t = 0; t < nbase; t++) {
                const uint64_t p  = base[t];
                const uint64_t js = (p * p - 1) / 2;   // index of p*p
                uint64_t start;
                if (js >= j0) {
                    start = js;
                } else {
                    uint64_t r = (j0 - js) % p;
                    start = r ? j0 + (p - r) : j0;
                }
                for (uint64_t j = start; j < j1; j += p)
                    buf[j - j0] = 1;
            }

            // 4. Count survivors.
            uint64_t c = 0;
            for (uint64_t i = 0; i < cnt; i++)
                c += (buf[i] == 0);
            total += c;
        }

        free(buf);
    }

    printf("%llu\n", (unsigned long long)total);
    return 0;
}
```

**How it works**

- **Odd-only storage:** Even numbers are skipped entirely, which halves memory and work.
- **Segmentation:** Each 64 KiB block fits in L2 cache, so marking stays cache-resident instead of streaming through 500 MB.
- **Per-segment start offsets:** Each base prime's first multiple inside a block is computed directly, so blocks are independent.
- **Parallelism:** Blocks are distributed across threads with `schedule(dynamic)`, and each thread has its own buffer and partial count.

I haven't compiled or benchmarked this in the sandbox, so treat the timing as an estimate. The expected output is 50,847,534 (π(10⁹)), which you can use to verify correctness.

Further speedups would come from bit-packing the segment (8× less memory traffic), pre-marking small primes with a wheel pattern, and tuning `SEG` for your CPU's cache size. Those change the constant factor, not the algorithm.

This is a segmented sieve of Eratosthenes in C with OpenMP. It stores only odd numbers, keeps each segment small enough to stay in cache, and sieves segments in parallel. The expected result is **50,847,534** (π(10⁹)).

```c
// primes_1e9.c
// Build: gcc -O3 -march=native -fopenmp primes_1e9.c -o primes_1e9 -lm
// Run:   ./primes_1e9

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <omp.h>

#define SEG_BITS 15                 /* 32768 odd numbers per segment (32 KB) */
#define SEG      (1u << SEG_BITS)

int main(void)
{
    const uint64_t N = 1000000000ULL;          /* count primes < N */
    const uint64_t lim = (uint64_t)sqrt((double)N) + 1;

    /* 1. Base sieve: odd primes up to sqrt(N). */
    char *composite = calloc(lim + 1, 1);
    uint32_t *bp = malloc(sizeof(uint32_t) * (lim / 2 + 1));
    size_t nbp = 0;
    for (uint64_t i = 3; i <= lim; i += 2) {
        if (!composite[i]) {
            bp[nbp++] = (uint32_t)i;
            for (uint64_t j = i * i; j <= lim; j += 2 * i)
                composite[j] = 1;
        }
    }
    free(composite);

    /* 2. Index i represents the odd number 2*i + 1.
          Odd numbers below N: indices 0 .. N/2 - 1. */
    const uint64_t total_idx = N / 2;
    const uint64_t nseg = (total_idx + SEG - 1) / SEG;
    uint64_t count = 0;

    #pragma omp parallel for schedule(dynamic) reduction(+:count)
    for (uint64_t g = 0; g < nseg; g++) {
        uint8_t seg[SEG];                       /* private per thread */
        const uint64_t s = g * SEG;
        uint64_t e = s + SEG;
        if (e > total_idx) e = total_idx;
        const uint64_t len = e - s;

        memset(seg, 0, len);
        const uint64_t low  = 2 * s + 1;
        const uint64_t high = 2 * (e - 1) + 1;

        if (s == 0) seg[0] = 1;                 /* 1 is not prime */

        /* Cross off odd multiples of each odd base prime. */
        for (size_t k = 0; k < nbp; k++) {
            const uint64_t p = bp[k];
            if (p * p > high) break;

            uint64_t m = (low + p - 1) / p;     /* ceil(low / p) */
            if (m < p) m = p;                   /* never mark p itself */
            if ((m & 1) == 0) m++;              /* keep multiplier odd */

            uint64_t x = p * m;                 /* first odd multiple in range */
            uint64_t idx = (x - 1) / 2 - s;     /* index of x in this segment */
            for (; idx < len; idx += p)         /* next odd multiple is +2p -> index +p */
                seg[idx] = 1;
        }

        for (uint64_t i = 0; i < len; i++)
            count += (seg[i] == 0);
    }

    count += 1;  /* the prime 2 */

    printf("%llu\n", (unsigned long long)count);

    free(bp);
    return 0;
}
```

**Why it's fast:**
- **Odd-only storage** halves both memory and work.
- **Segmentation** keeps the working set in L1/L2 cache, so the sieve is not memory-bound the way a full 1-billion-byte array would be.
- **Parallel segments** use OpenMP's dynamic scheduling, with each thread sieving its own segment buffer, so there is no shared state apart from the final reduction.
- **Only primes up to √N (about 31,623)** are used for crossing off.

I haven't benchmarked this in this session. On a typical multicore machine it should finish in well under a second, and a single-threaded version will take longer. If you want more speed, the next steps are bit-packing the segment (8 numbers per byte), using a wheel (skipping multiples of 3 and 5), or tuning `SEG_BITS` to your L2 cache size.

