<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const highEl = document.getElementById('high');
  const overlay = document.getElementById('overlay');
  const titleEl = document.getElementById('title');
  const messageEl = document.getElementById('message');

  const GRID = 20;                 // cells per row/column
  const CELL = canvas.width / GRID;
  const START_SPEED = 120;         // ms per step
  const MIN_SPEED = 50;
  const SPEED_STEP = 3;            // faster per food eaten

  const HIGH_KEY = 'snake-high-score';
  let highScore = Number(localStorage.getItem(HIGH_KEY)) || 0;
  highEl.textContent = highScore;

  let snake, dir, nextDir, food, score, speed, state, timer;

  const DIRS = {
    ArrowUp: [0, -1], w: [0, -1], W: [0, -1],
    ArrowDown: [0, 1], s: [0, 1], S: [0, 1],
    ArrowLeft: [-1, 0], a: [-1, 0], A: [-1, 0],
    ArrowRight: [1, 0], d: [1, 0], D: [1, 0],
  };

  function reset() {
    const mid = Math.floor(GRID / 2);
    snake = [{ x: mid, y: mid }, { x: mid - 1, y: mid }, { x: mid - 2, y: mid }];
    dir = [1, 0];
    nextDir = [1, 0];
    score = 0;
    speed = START_SPEED;
    food = spawnFood();
    updateScore();
  }

  function spawnFood() {
    while (true) {
      const p = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
      if (!snake.some(s => s.x === p.x && s.y === p.y)) return p;
    }
  }

  function updateScore() {
    scoreEl.textContent = score;
    if (score > highScore) {
      highScore = score;
      localStorage.setItem(HIGH_KEY, highScore);
      highEl.textContent = highScore;
    }
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir[0], y: snake[0].y + dir[1] };

    const hitWall = head.x < 0 || head.y < 0 || head.x >= GRID || head.y >= GRID;
    const hitSelf = snake.some(s => s.x === head.x && s.y === head.y);
    if (hitWall || hitSelf) return gameOver();

    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
      score++;
      speed = Math.max(MIN_SPEED, speed - SPEED_STEP);
      food = spawnFood();
      updateScore();
    } else {
      snake.pop();
    }
    draw();
    timer = setTimeout(step, speed);
  }

  function draw() {
    ctx.fillStyle = getComputedStyle(canvas).backgroundColor;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // food
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--food');
    ctx.beginPath();
    ctx.arc(food.x * CELL + CELL / 2, food.y * CELL + CELL / 2, CELL / 2 - 2, 0, Math.PI * 2);
    ctx.fill();

    // snake
    snake.forEach((s, i) => {
      ctx.fillStyle = i === 0 ? '#8bc34a' : '#4caf50';
      ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function start() {
    clearTimeout(timer);
    reset();
    state = 'running';
    hideOverlay();
    draw();
    timer = setTimeout(step, speed);
  }

  function pause() {
    if (state === 'running') {
      clearTimeout(timer);
      state = 'paused';
      showOverlay('Paused', 'Press Space to resume');
    } else if (state === 'paused') {
      state = 'running';
      hideOverlay();
      timer = setTimeout(step, speed);
    }
  }

  function gameOver() {
    state = 'over';
    clearTimeout(timer);
    showOverlay('Game Over', `Score: ${score} · Press Enter to play again`);
  }

