      if (state === 'idle') start();
      else return;
    }
    if (state !== 'running') return;

    // Prevent reversing directly into the body
    if (d[0] === -dir[0] && d[1] === -dir[1]) return;
    nextDir = d;
  });

  // initial screen
  reset();
  draw();
  state = 'idle';
  showOverlay('Snake', 'Press any arrow key or WASD to start');
