<p>Arrow keys / WASD to move · Space to pause/restart</p>
<script>
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const N = 20, S = canvas.width / N;
let snake, dir, nextDir, food, score, best = +localStorage.getItem('snakeBest') || 0;
let timer, paused, over;
document.getElementById('best').textContent = best;

function reset() {
  snake = [{x:10,y:10},{x:9,y:10},{x:8,y:10}];
  dir = nextDir = {x:1,y:0};
  score = 0; paused = false; over = false;
  document.getElementById('score').textContent = 0;
  placeFood();
  clearInterval(timer);
  timer = setInterval(tick, 110);
  draw();
}

function placeFood() {
  do {
    food = {x:Math.floor(Math.random()*N), y:Math.floor(Math.random()*N)};
  } while (snake.some(s => s.x===food.x && s.y===food.y));
}

function tick() {
  if (paused || over) return;
  dir = nextDir;
  const head = {x:snake[0].x+dir.x, y:snake[0].y+dir.y};
  if (head.x<0 || head.y<0 || head.x>=N || head.y>=N || snake.some(s => s.x===head.x && s.y===head.y)) {
    over = true;
    if (score > best) { best = score; localStorage.setItem('snakeBest', best); document.getElementById('best').textContent = best; }
    draw();
    return;
  }
  snake.unshift(head);
  if (head.x===food.x && head.y===food.y) {
    score++;
    document.getElementById('score').textContent = score;
    placeFood();
  } else snake.pop();
  draw();
}

function draw() {
  ctx.fillStyle = '#1b1b1b';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.fillStyle = '#e53935';
  ctx.beginPath();
  ctx.arc(food.x*S+S/2, food.y*S+S/2, S/2-2, 0, Math.PI*2);
  ctx.fill();
