#!/usr/bin/env python3
"""Print the 10 most common words in a text file.

Usage: python3 word_count.py FILE
"""

import re
import sys
from collections import Counter

# A word is a run of letters, optionally joined by apostrophes (so "don't" counts once).
WORD_PATTERN = re.compile(r"[^\W\d_]+(?:'[^\W\d_]+)*")


def count_words(text):
    return Counter(match.group().lower() for match in WORD_PATTERN.finditer(text))


def main():
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} FILE")

    try:
        with open(sys.argv[1], encoding="utf-8") as f:
            text = f.read()
    except OSError as err:
        sys.exit(f"Error: cannot read {sys.argv[1]}: {err}")

    for word, count in count_words(text).most_common(10):
        print(f"{word}\t{count}")


if __name__ == "__main__":
    main()

