#!/usr/bin/env python3
"""Print the 10 most common words in a text file, with their counts."""

import re
import sys
from collections import Counter


def count_words(path):
    with open(path, encoding="utf-8", errors="replace") as f:
        text = f.read()
    # Words are runs of letters/digits/apostrophes, compared case-insensitively.
    words = re.findall(r"[a-z0-9']+", text.lower())
    return Counter(w.strip("'") for w in words if w.strip("'"))


def main():
    if len(sys.argv) != 2:
        sys.exit(f"usage: {sys.argv[0]} <text file>")

    try:
        counts = count_words(sys.argv[1])
    except OSError as e:
        sys.exit(f"error: {e}")

    for word, n in counts.most_common(10):
        print(f"{word}\t{n}")


if __name__ == "__main__":
    main()

