from dijkstra import dijkstra, shortest_path


class DijkstraTests(unittest.TestCase):
    def setUp(self):
        self.graph = {
            "A": {"B": 7, "C": 9, "F": 14},
            "B": {"A": 7, "C": 10, "D": 15},
            "C": {"A": 9, "B": 10, "D": 11, "F": 2},
            "D": {"B": 15, "C": 11, "E": 6},
            "E": {"D": 6, "F": 9},
            "F": {"A": 14, "C": 2, "E": 9},
        }

    def test_distances(self):
        distances, _ = dijkstra(self.graph, "A")
        self.assertEqual(distances, {"A": 0, "B": 7, "C": 9, "D": 20, "E": 20, "F": 11})

    def test_shortest_path(self):
        self.assertEqual(shortest_path(self.graph, "A", "E"), (20, ["A", "C", "F", "E"]))

    def test_source_to_self(self):
        self.assertEqual(shortest_path(self.graph, "A", "A"), (0, ["A"]))

    def test_unreachable(self):
        graph = {"A": {"B": 1}, "B": {}, "C": {}}
        self.assertEqual(shortest_path(graph, "A", "C"), (None, None))

    def test_directed_edges(self):
        graph = {"A": {"B": 1}, "B": {}}
        self.assertEqual(shortest_path(graph, "B", "A"), (None, None))

    def test_zero_weight_edges(self):
        graph = {"A": {"B": 0}, "B": {"C": 0}, "C": {}}
        self.assertEqual(shortest_path(graph, "A", "C"), (0, ["A", "B", "C"]))

    def test_prefers_longer_hop_count_when_cheaper(self):
        graph = {
            "A": {"B": 10, "C": 1},
            "C": {"D": 1},
            "D": {"B": 1},
            "B": {},
        }
        self.assertEqual(shortest_path(graph, "A", "B"), (3, ["A", "C", "D", "B"]))

    def test_negative_weight_raises(self):
        with self.assertRaises(ValueError):
            dijkstra({"A": {"B": -1}, "B": {}}, "A")

    def test_missing_source_raises(self):
        with self.assertRaises(KeyError):
            dijkstra({"A": {}}, "Z")


if __name__ == "__main__":
    unittest.main()

import math
import unittest

from dijkstra import dijkstra, shortest_path


class DijkstraTests(unittest.TestCase):
    def test_classic_example(self):
        graph = {
            "A": [("B", 7), ("C", 9), ("F", 14)],
            "B": [("A", 7), ("C", 10), ("D", 15)],
            "C": [("A", 9), ("B", 10), ("D", 11), ("F", 2)],
            "D": [("B", 15), ("C", 11), ("E", 6)],
            "E": [("D", 6), ("F", 9)],
            "F": [("A", 14), ("C", 2), ("E", 9)],
        }
        path, cost = shortest_path(graph, "A", "E")
        self.assertEqual(path, ["A", "C", "F", "E"])
        self.assertEqual(cost, 20)

    def test_source_to_itself(self):
        graph = {"A": [("B", 1)], "B": []}
        self.assertEqual(shortest_path(graph, "A", "A"), (["A"], 0))

    def test_unreachable_target(self):
        graph = {"A": [("B", 1)], "B": [], "C": []}
        self.assertEqual(shortest_path(graph, "A", "C"), (None, math.inf))

    def test_prefers_longer_hop_count_when_cheaper(self):
        graph = {
            "S": [("T", 10), ("X", 1)],
            "X": [("Y", 1)],
            "Y": [("T", 1)],
            "T": [],
        }
        path, cost = shortest_path(graph, "S", "T")
        self.assertEqual(path, ["S", "X", "Y", "T"])
        self.assertEqual(cost, 3)

    def test_zero_weight_edges(self):
        graph = {"A": [("B", 0)], "B": [("C", 0)], "C": []}
        self.assertEqual(shortest_path(graph, "A", "C"), (["A", "B", "C"], 0))

    def test_directed_edges(self):
        graph = {"A": [("B", 1)], "B": []}
        self.assertEqual(shortest_path(graph, "B", "A"), (None, math.inf))

    def test_dist_and_prev_maps(self):
        graph = {"A": [("B", 2), ("C", 5)], "B": [("C", 1)], "C": []}
        dist, prev = dijkstra(graph, "A")
        self.assertEqual(dist, {"A": 0, "B": 2, "C": 3})
        self.assertEqual(prev, {"A": None, "B": "A", "C": "B"})

    def test_negative_weight_rejected(self):
        graph = {"A": [("B", -1)], "B": []}
        with self.assertRaises(ValueError):
            dijkstra(graph, "A")

    def test_unknown_source_rejected(self):
        with self.assertRaises(KeyError):
            dijkstra({"A": []}, "Z")


if __name__ == "__main__":
    unittest.main()

