// Count primes below 1,000,000,000 with a multithreaded, odd-only, segmented sieve.
// Build: gcc -O3 -march=native -fopenmp primes.c -o primes -lm
// Expected output: 50847534

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LIMIT 1000000000ULL      /* count primes strictly below this */
#define SEG_ODDS (1u << 18)      /* odd numbers per segment: 256 KiB, cache friendly */

int main(void) {
    // Base primes: all odd primes up to sqrt(LIMIT)
    uint64_t root = (uint64_t)sqrt((double)LIMIT) + 2;
    char *is = calloc(root + 1, 1);
    uint32_t *base = malloc(sizeof(uint32_t) * (root + 1));
    size_t nb = 0;
    for (uint64_t i = 3; i <= root; i += 2) {
        if (!is[i]) {
            base[nb++] = (uint32_t)i;
            for (uint64_t j = i * i; j <= root; j += 2 * i) is[j] = 1;
        }
    }
    free(is);

    // Index i in a segment represents the odd number lo + 2*i
    uint64_t total_odds = LIMIT / 2;                       // odd numbers 1..LIMIT-1
    uint64_t nseg = (total_odds + SEG_ODDS - 1) / SEG_ODDS;
    uint64_t count = 0;

    #pragma omp parallel reduction(+:count)
    {
        unsigned char *comp = malloc(SEG_ODDS);

        #pragma omp for schedule(dynamic, 1)
        for (uint64_t s = 0; s < nseg; s++) {
            uint64_t lo = 1 + 2 * (s * SEG_ODDS);
            uint64_t valid = total_odds - s * SEG_ODDS;
            if (valid > SEG_ODDS) valid = SEG_ODDS;
            uint64_t hi = lo + 2 * valid;                  // exclusive upper bound

            memset(comp, 0, SEG_ODDS);
            if (s == 0) comp[0] = 1;                       // 1 is not prime

            for (size_t k = 0; k < nb; k++) {
                uint64_t p = base[k];
                uint64_t pp = p * p;
                if (pp >= hi) break;

                uint64_t m;                                // first odd multiple of p to mark
                if (pp >= lo) {
                    m = pp;
                } else {
                    m = (lo + p - 1) / p * p;
                    if ((m & 1) == 0) m += p;
                }
                // Stepping by p in index space == stepping by 2p in value space
                for (uint64_t j = (m - lo) / 2; j < valid; j += p) comp[j] = 1;
            }

            for (uint64_t j = 0; j < valid; j++) count += !comp[j];
        }

        free(comp);
    }

    free(base);
    printf("%llu\n", (unsigned long long)(count + 1));    // +1 for the prime 2
    return 0;
}

