// sha256tool prints the SHA-256 digest of one or more files.
//
// Usage:
//
//	sha256tool FILE [FILE...]
//	sha256tool -        # read from stdin
//
// Output uses the same format as sha256sum: "<hex digest>  <name>".
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
)

const usage = `Usage: sha256tool FILE [FILE...]
       sha256tool -        (read from stdin)

Prints the SHA-256 digest of each file as "<digest>  <name>".`

// digest streams r through SHA-256 and returns the lowercase hex digest.
func digest(r io.Reader) (string, error) {
	h := sha256.New()
	if _, err := io.Copy(h, r); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// hashPath opens the named file (or stdin for "-") and returns its digest.
func hashPath(path string) (string, error) {
	if path == "-" {
		return digest(os.Stdin)
	}
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	return digest(f)
}

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, usage)
		os.Exit(2)
	}
	if args[0] == "-h" || args[0] == "--help" {
		fmt.Println(usage)
		return
	}

	status := 0
	for _, path := range args {
		sum, err := hashPath(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "sha256tool: %v\n", err)
			status = 1
			continue
		}
		fmt.Printf("%s  %s\n", sum, path)
	}
	os.Exit(status)
}

