// Reads standard input when no file is given or when a file is "-".
package main

import (
	"crypto/sha256"
	"fmt"
	"io"
	"os"
)

const usage = `Usage: %s [FILE]...
Print the SHA-256 digest of each FILE, in the format "<hash>  <file>".
With no FILE, or when FILE is "-", read standard input.
`

func main() {
	if len(os.Args) > 1 && (os.Args[1] == "-h" || os.Args[1] == "--help") {
		fmt.Fprintf(os.Stdout, usage, os.Args[0])
		return
	}

	args := os.Args[1:]
	if len(args) == 0 {
		args = []string{"-"}
	}

	status := 0
	for _, name := range args {
		if err := hashOne(name); err != nil {
			fmt.Fprintf(os.Stderr, "%s: %v\n", os.Args[0], err)
			status = 1
		}
	}
	os.Exit(status)
}

func hashOne(name string) error {
	var r io.Reader
	if name == "-" {
		r = os.Stdin
	} else {
		f, err := os.Open(name)
		if err != nil {
			return err
		}
		defer f.Close()
		r = f
	}

	h := sha256.New()
	// Stream the file so large inputs don't need to fit in memory.
	if _, err := io.Copy(h, r); err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}

	fmt.Printf("%x  %s\n", h.Sum(nil), name)
	return nil
}

