			continue
		}
		fmt.Printf("%x  %s\n", digest, path)
	}
	os.Exit(status)
}

// hashFile streams the file through SHA-256 so large files are not loaded into memory.
func hashFile(path string) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return h.Sum(nil), nil
}
